function minOperations(nums) {
  let operations = 0;
  let previous = nums[0];

  for (let i = 1; i < nums.length; i++) {
    const needed = previous + 1;
    if (nums[i] < needed) {
      operations += needed - nums[i];
      previous = needed;
    } else {
      previous = nums[i];
    }
  }
  return operations;
}

